const triageLanes=[['critical','Critical',[4]],['reply','Needs reply',[0,2]],['waiting','Waiting on others',[5]],['fyi','FYI',[1,3]],['low','Low priority',[6]],['decisions','Decisions',[7]]];
pages.inbox=()=>{const lane=triageLanes.find(x=>x[0]===state.triageLane)||triageLanes[0],items=mailItems.filter(m=>lane[2].includes(m.id)&&!state.archived.includes(m.id)&&!state.snoozedMessages?.[m.id]),m=items.find(x=>x.id===state.selectedMail)||items[0];return `${head('Inbox','Outlook, Teams and plugin notifications · every priority has a reason',btn('Sending policy & log','sending-policy','shield')+btn('Triage rules','triage-rules','sliders')+linkBtn('Files','files.html','folder'))}<nav class="view-tabs">${triageLanes.map(([id,label,ids])=>`<button class="${state.triageLane===id?'active':''}" data-action="triage-lane:${id}">${label} ${tag(ids.filter(n=>!state.archived.includes(n)).length,id==='critical'?'red':'')}</button>`).join('')}</nav>${!graphReady('mail')||!graphReady('chats')?'<div class="notice amber mb">Cached sample messages. Reconnect the missing Microsoft 365 capabilities to sync new mail and chats. <a class="text-link" href="settings-connections.html">Manage connection</a></div>':''}<div class="panel inbox-layout"><aside class="inbox-list">${items.map(i=>`<button class="mail-item ${i.id===m?.id?'active':''}" data-action="open-mail:${i.id}"><div class="between"><strong class="small">${i.from}</strong><span class="dim" style="font-size:9px">${i.time}</span></div><h3>${i.subject}</h3><p>${i.preview}</p><div class="flex mt">${tag(i.channel==='mail'?'Outlook':i.channel==='teams'?'Teams':'Plugin','blue')}${i.draft?tag('Reply prepared','green'):''}</div></button>`).join('')||`<div class="widget-body"><p>No items in this lane.</p>${btn('Restore sample inbox','restore-inbox','undo','sm')}</div>`}</aside><article class="mail-body">${m?`<div class="between"><div class="flex"><span class="avatar">${m.initials}</span><div><strong class="small">${m.from}</strong><p class="small">To you · ${m.channel==='mail'?'Outlook mail':'Workspace channel'}</p></div></div><button class="icon-btn" data-action="archive-mail:${m.id}" aria-label="Archive message">${icon('archive')}</button></div><h2>${m.subject}</h2>${m.id===4?`<div class="critical-strip"><div class="grow"><strong>${state.criticalAck?'Acknowledged by you':'Critical · VIP + outage rule'}</strong><p>“Payments have been failing” · Rule matched before AI triage · AI confidence 98%</p></div>${btn('Why?','critical-why','info','sm')}</div>`:`<div class="readiness mb">${icon('filter')}Priority: ${lane[1]} · ${m.id===7?'Review required before Knowledge changes':'Rule + source content, available in the audit log'}</div>`}<div class="message">${esc(m.body).replace(/\n/g,'<br>')}</div><div class="flex wrap mt"><a class="chip" href="space.html">Workspace redesign</a><a class="chip" href="knowledge-pages.html?doc=Workspace%20principles">Relevant knowledge</a>${m.id===4?btn(state.criticalAck?'Acknowledged':'Acknowledge','ack-critical','check','primary sm'):''}${btn('Snooze','snooze-message:'+m.id,'clock','sm')}${btn('Save source','save-mail-source:'+m.id,'book','sm')}</div><div class="line"></div>${m.draft?`<div class="notice"><div class="between"><strong>Prepared reply</strong>${tag(state.sentMails?.includes(m.id)?'SIMULATED SENT':'NOT SENT','blue')}</div><p class="prose mt">${esc(state.mailDrafts?.[m.id]||m.draft)}</p><div class="flex wrap mt">${btn('Review & reply','draft-reply:'+m.id,'edit','primary sm')}${btn('Sources & recipe','reply-evidence:'+m.id,'book','sm')}</div></div>`:m.id===7?linkBtn('Compare conflicting pages','knowledge-health.html','code','primary'):btn('Ask about this message','context-ask:inbox','spark','sm')}`:empty('This lane is clear','Review another lane or restore the sample messages.',btn('Restore sample inbox','restore-inbox','undo'))}</article></div>`};
const captureSources=[['Microsoft Teams','teams','Detected · Product sync','Detectable'],['Google Meet','globe','Choose a meeting tab','Tab scope'],['Zoom','video','Running · no meeting yet','Ask at start'],['Slack huddle','chat','Select the active huddle','Manual'],['Any app or browser tab','monitor','Webex, WhatsApp or another app','Pick each time'],['System audio + microphone','headphones','Everything you hear + your voice','Broad scope'],['In the room','users','Microphone · on-device speakers','Local'],['Voice memo','mic','Just your thoughts','Minutes now']];
pages.capture=()=>`${head('Capture','Your source, your scope, your recording decision.',btn('Import recording','import-recording','upload')+linkBtn('Detection rules','settings-capture.html#detection-rules','settings'))}<nav class="view-tabs"><a href="meetings.html">All meetings</a><a class="active" href="capture.html">Capture</a><a href="recipes.html">Minutes recipes</a></nav>${state.recording?liveCapture():`${state.armedMeeting?`<div class="notice mb"><strong>Armed for ${esc(state.armedMeeting)}</strong> · You opted in. Recording starts only when the selected meeting is detected. ${btn('Cancel','cancel-arm','close','sm')}${btn('Simulate meeting start','simulate-meeting-start','play','primary sm')}</div>`:''}${!state.detectionDismissed?`<div class="panel mb"><div class="list-row"><span class="round-icon">${icon('teams')}</span><div class="grow"><h3>Microsoft Teams · Product sync</h3><p>Detected meeting · Personal workspace · 10:00 · 4 people</p></div>${btn('Not this','dismiss-detection','close','sm')}${btn('Record','record-meeting','mic','primary sm')}</div></div>`:''}<div class="capture-sources">${captureSources.map(([name,ico,desc,status])=>`<button class="capture-source ${state.captureSource===name?'active':''}" data-action="capture-source:${name}">${icon(ico)}<h3>${name}</h3><p>${desc}</p>${tag(status,name==='Microsoft Teams'?'green':'')}</button>`).join('')}</div><div class="grid2 mt">${panel('Selected source',`<div class="widget-body"><h2>${esc(state.captureSource)}</h2><p class="mt">${state.captureSource.includes('tab')||state.captureSource==='Google Meet'?'Choose one tab. The rest of your browser is excluded.':state.captureSource.startsWith('System')?'This source includes all system audio. Check other apps before starting.':'Capture only the selected source and your microphone as separate tracks.'}</p><div class="flex wrap mt">${btn('Configure & record','record-meeting','mic','primary')}${btn('Record when it starts','arm-capture:Product sync','clock')}</div></div>`,'','mic')}${panel('What happens to a recording',`<div class="widget-body"><ol class="prose"><li>You choose a source and confirm participants know.</li><li>Audio stays on this device; live transcription is optional.</li><li>Your recipe sets the minutes delay and AI profile.</li><li>Review minutes, actions and Knowledge diffs before saving or sharing.</li></ol><div class="notice">This prototype simulates capture. It does not access a microphone or other applications.</div></div>`,'','shield')}</div>`}`;
function liveCapture(){return `<div class="panel panel-pad mb"><div class="between"><div class="record-status"><span class="recording-dot"></span><strong>${state.recordingPaused?'Paused':'Recording'} · ${esc(state.recordTitle||'Product sync')}</strong>${tag(state.captureSource,'blue')}</div><div class="flex">${btn(state.recordingPaused?'Resume':'Pause','pause-capture',state.recordingPaused?'play':'pause')}${btn('Stop recording','stop-recording','stop','danger')}</div></div><div class="waveform recording">${Array.from({length:80},(_,i)=>`<i style="--h:${12+i*13%45}px;--delay:${i*.03}s"></i>`).join('')}</div><div class="between small dim"><span>04:28 · Sample capture · 2 tracks</span><span>On-device transcription · English</span></div></div><div class="grid2"><div class="panel"><nav class="view-tabs" style="padding:0 16px;margin:0">${['Transcript','Meeting chat','Screens'].map(t=>`<button class="${(state.captureTab||'Transcript')===t?'active':''}" data-action="capture-tab:${t}">${t}</button>`).join('')}</nav>${state.captureTab==='Meeting chat'?'<div class="live-transcript"><div class="prose"><strong>Jamie · 10:02</strong><p>I added the API inventory to the shared folder.</p><a class="text-link" href="files.html">Plugin host inventory.md</a></div></div>':state.captureTab==='Screens'?'<div class="widget-body"><div class="notice">Screen capture is off. Audio recording does not enable screenshots.</div><p class="mt prose">A separate opt-in would choose the app or display and retention period.</p></div>':`<div class="live-transcript">${[['00:18','AM','Let’s keep the first experience useful without any platform account.'],['01:02','JT','The Echo packages can stay unchanged if the host provides the same services and UI slots.'],['02:14','You','We should test each plugin capability before calling it compatible.'],['03:35','AM','I’ll review the capture controls today. Can you send the prototype after this call?']].map(([t,n,txt])=>`<div class="transcript-line"><span class="dim">${t}</span><strong>${n}</strong><p>${txt}</p></div>`).join('')}</div>`}<div class="panel-foot">${btn('What did I miss?','capture-assist:miss','spark','sm')}${btn('Suggest a question','capture-assist:question','chat','sm')}</div></div><div class="panel"><div class="panel-head"><h2>${icon('edit')}Live notes</h2>${tag('Draft')}</div><div class="live-notes"><h3>Decisions</h3><ul><li>Direct Claude Code is a complete starting profile.</li><li>Preserve the Echo package contract; validate each host service.</li></ul><h3>Actions</h3><ul><li>Alex: review capture controls · today.</li><li>You: share the prototype after this meeting.</li></ul><h3>Open question</h3><p class="prose">How should a plugin request a new folder grant?</p><label class="field mt"><span>Your private note</span><textarea id="live-private-note" placeholder="Add a note for the minutes…">${esc(state.livePrivateNote||'')}</textarea></label></div></div></div>`}
const ingestChanges=[{id:'decisions',path:'knowledge/workspace/decisions.md',remove:'Plugin compatibility will be confirmed later.',add:'Keep Echo packages unchanged. Validate every host service before marking compatibility.',source:'Design review · 02:14'}, {id:'risks',path:'knowledge/workspace/risks.md',remove:'No known plugin risks.',add:'AGPL host reuse and client API parity require review before implementation.',source:'Plugin investigation · source notes'}, {id:'daily',path:'knowledge/notes/2026-11-16.md',remove:'',add:'Product sync: review the native host adapter and capture controls.',source:'Design review · 03:35'}, {id:'taxonomy',path:'TAG_TAXONOMY.md',remove:'',add:'plugin-host: desktop host and package compatibility work',source:'AI tag proposal · optional'}];
function activeIngestChanges(){if(state.ingestSource==='mail')return [{id:'mail-incident',path:'knowledge/incidents/checkout.md',remove:'',add:'Payments failing since 08:18. Jamie investigates callbacks. Recovery ETA unconfirmed.',source:'Alex · Outlook · 08:22'}];if(state.ingestSource==='doc')return [{id:'doc-direction',path:'knowledge/workspace/direction.md',remove:'',add:'Direct Claude Code and local knowledge form an independent personal workspace.',source:'Workspace direction.md · local file'}];return ingestChanges}
pages['knowledge-ingest']=()=>`${vaultHeader(btn('Add source','add-source','plus','primary'))}<div class="flow-row mb">${[['Queue','Source files','No model'],['Convert','Text + metadata','No model'],['Route & propose','Selected skill + profile','AI'],['Index & link','Catalog + backlinks','No model'],['Review & commit','Selected file diffs','You']].map(([a,b,c],i)=>`<div class="flow-step ${c==='AI'?'ai':''}"><div class="step-type">${i+1} · ${c}</div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><div class="panel module-layout"><aside class="module-list"><div class="module-section">Incoming sources · 6</div>${[['meeting','Design review','Proposed · 4 file changes'],['mail','Checkout incident','New · Outlook thread'],['doc','Workspace direction.md','New · local file'],['duplicate','Design review (Teams)','Possible duplicate'],['private','Voice memo','Skipped · private']].map(([id,n,s])=>`<button class="module-item ${(state.ingestSource||'meeting')===id?'active':''}" data-action="ingest-source:${id}"><strong>${n}</strong><small>${s}</small></button>`).join('')}<div class="module-section">Unified ledger</div><button class="module-item" data-action="ingest-ledger"><strong>3 source systems</strong><small>Meeting sync · raw inbox · approvals</small></button></aside><section class="module-detail">${ingestDetail()}</section></div>`;
function ingestDetail(){const selected=state.ingestSource||'meeting',changes=activeIngestChanges();if(selected==='private')return `<h2>Private memo · skipped</h2><p class="prose mt">“Thinking out loud about the next iteration.”</p><div class="notice mt">This source stays private. It is excluded from ingestion and Recall.</div>${btn('Return to queue','ingest-source:meeting','back','sm')}`;if(selected==='duplicate')return `<h2>Possible duplicate</h2><p class="prose mt">This Teams transcript and the local recording share the same meeting ID and time.</p><div class="grid2 mt"><div class="info-box"><h3>Local recording</h3><p>42:18 · 7,812 words · 4 speakers<br>Includes private notes</p></div><div class="info-box"><h3>Teams transcript</h3><p>42:10 · 7,590 words · 4 speakers<br>Uploaded at 09:45</p></div></div><div class="flex mt">${btn('Keep local as source','resolve-duplicate:local','check','primary')}${btn('Keep Teams as source','resolve-duplicate:teams','check')}</div>`;return `<div class="module-subhead"><div><h2>${selected==='meeting'?'Workspace design review':selected==='mail'?'Checkout incident':'Workspace direction.md'}</h2><p class="small dim">${selected==='meeting'?'Meeting · 42 min · transcript + reviewed notes':'Selected source · raw content is kept intact'}</p></div>${btn('Read source','ingest-read-source','file','sm')}</div><div class="readiness">${icon('shield')}Claude Code · process-inbox · 4.2k tokens · estimated $0.18 · cap $0.50</div><div class="between mt"><h3>Proposed changes · ${state.approvedChanges.length} approved</h3>${btn('Redo with instruction','ingest-redo','refresh','sm')}</div>${changes.map(c=>`<div class="diff-block"><div class="diff-head"><input type="checkbox" data-ingest-change="${c.id}" aria-label="Approve ${c.path}" ${state.approvedChanges.includes(c.id)?'disabled checked':c.id!=='taxonomy'?'checked':''}><strong class="grow">${c.path}</strong>${tag(state.approvedChanges.includes(c.id)?'Approved':c.id==='taxonomy'?'Needs you':'Proposed',state.approvedChanges.includes(c.id)?'green':'')}</div>${c.remove?`<div class="diff-line remove">− ${c.remove}</div>`:''}<div class="diff-line add">+ ${c.add}</div><div class="diff-line context">Source: ${c.source} · original unchanged</div></div>`).join('')}<div class="flex wrap mt">${btn('Keep in queue','ingest-keep','clock')}${btn('Approve selected changes','ingest-approve-selected','check','primary')}</div><div class="subtle-note">Only selected diffs are applied. One local commit records the sources, skill and approved files. No real files are modified by this prototype.</div>`}
const healthFindings=[['contradiction','Contradicting launch date','AI · Needs you','Two sources disagree: 12 December / 9 January.'],['ledger','Source ledgers disagree','No model · Needs you','One Teams transcript has no matching source entry.'],['tag','New tag proposal','AI · Needs you','plugin-host needs a vocabulary decision.'],['links','Broken links','No model','14 broken links · 11 unambiguous renames.'],['index','Missing from index','No model','7 pages are absent from CATALOG.md.'],['frontmatter','Missing frontmatter','No model','3 pages need a source reference.'],['schema','Schema drift','AI','2 pages use an older decision template.'],['templates','Template checks','No model','1 template has a missing required field.'],['oversized','Oversized index','No model','Split a 100 KB index into sections.'],['duplicates','Potential duplicates','AI','2 sources may describe the same meeting.'],['orphans','Isolated pages','No model','12 pages have no incoming links.'],['stale','Stale claims','AI','5 claims have not been reviewed in 90 days.']];
pages['knowledge-health']=()=>`${vaultHeader(btn('Run checks','run-knowledge-health','refresh','primary'))}<div class="panel panel-pad mb"><div class="health-score"><div class="score-ring">${82+Math.min(15,state.healthResolved.length*3)}<small>/ 100 health</small></div><div class="grow"><h2>Wiki health</h2><p class="small dim">+8 in 30 days · latest run 09:52 · next nightly check 22:00</p><div class="score-parts mt">${[['Links','21 / 25'],['Index','18 / 20'],['Properties','13 / 15'],['Consistency','19 / 25'],['Freshness','13 / 15']].map(([a,b])=>`<div>${a}<b>${b}</b><div class="bar"><i></i></div></div>`).join('')}</div></div></div></div><div class="panel module-layout"><aside class="module-list"><div class="module-section">12 finding types</div>${healthFindings.map(([id,t,kind,desc])=>`<button class="module-item ${(state.healthSelection||'contradiction')===id?'active':''}" data-action="health-select:${id}"><strong>${state.healthResolved.includes(id)?'✓ ':''}${t}</strong><small>${kind}</small></button>`).join('')}</aside><section class="module-detail">${healthDetail()}</section></div>`;
function healthDetail(){const [id,title,kind,desc]=healthFindings.find(x=>x[0]===(state.healthSelection||'contradiction'));if(state.healthResolved.includes(id))return `<h2>${title}</h2><div class="notice green mt">This finding was resolved in the sample vault. Other finding types remain open.</div>${btn('Undo this repair','undo-health:'+id,'undo','sm')}`;return `<div class="module-subhead"><div><h2>${title}</h2><p class="small">${desc}</p></div>${tag(kind,id==='contradiction'?'red':'blue')}</div>${id==='contradiction'?`<div class="grid2"><div class="info-box"><h3>Older · roadmap.md</h3><p>“Phase 2 go-live: 12 December.”</p><div class="subtle-note">Edited 12 Nov · client roadmap</div></div><div class="info-box"><h3>Newer · decisions.md</h3><p>“Go-live moves to 9 January for release readiness.”</p><div class="subtle-note">Review minutes · 16 Nov · Alex</div></div></div><div class="notice mt">Suggested resolution: the dated decision supersedes the roadmap. Choose the source you trust.</div><div class="flex wrap mt">${btn('Keep 12 December','choose-fact:December','file')}${btn('Use 9 January','choose-fact:January','check','primary')}</div>`:`<div class="diff-block"><div class="diff-head">knowledge/workspace/${id}.md</div><div class="diff-line remove">− ${id==='links'?'[[Workspace vision]]':'Existing entry needs review'}</div><div class="diff-line add">+ ${id==='links'?'[[Workspace principles]]':id==='tag'?'plugin-host · host compatibility and native services':'Corrected entry with source and schema'}</div><div class="diff-line context">${kind.startsWith('No model')?'Deterministic check · no AI call':'AI proposal · no write without your review'}</div></div><div class="flex mt">${btn('Keep finding open','close-finding','clock')}${btn('Approve this repair','resolve-health:'+id,'check','primary')}</div>`}<div class="subtle-note">Approval applies to this finding only. Read-only folder grants block every write.</div>`}
const oldRecipeEditor=showRecipeEditor;
pages.recipes=()=>{const list=recipeList(),r=list.find(x=>x.id===state.selectedRecipe)||list[0];return `${head('Minutes recipes','First matching rule wins · your skill, template, timing and AI profile',btn('New recipe','edit-recipe:new','plus','primary'))}<nav class="view-tabs"><a href="meetings.html">All meetings</a><a href="capture.html">Capture</a><a class="active" href="recipes.html">Minutes recipes</a></nav><div class="panel module-layout"><aside class="module-list"><div class="module-section">Recipes · checked in order</div>${list.map((x,i)=>`<button class="module-item ${r.id===x.id?'active':''}" data-action="select-recipe:${x.id}"><strong>${i+1}. ${esc(x.name)}</strong><small>${esc(x.timing)}</small></button>`).join('')}</aside><section class="module-detail"><div class="module-subhead"><div><h2>${esc(r.name)}</h2><p class="small dim">Version ${state.recipeVersion||3} · Yours · ${esc(r.profile)}</p></div><div class="flex">${btn('Edit','edit-recipe:'+r.id,'edit','sm')}${btn('Test','test-recipe:'+r.id,'play','primary sm')}</div></div><nav class="view-tabs">${['Rules','Timing','Skill & prompt','Template','Outputs','History'].map(t=>`<button class="${state.recipeTab===t?'active':''}" data-action="recipe-tab:${t}">${t}</button>`).join('')}</nav>${recipeDetail(r)}</section></div>`};
function recipeDetail(r){switch(state.recipeTab){case 'Timing':return `<h3>When minutes are written</h3><div class="panel mt">${settingRow('Delay after meeting','0–60 minutes; new notes restart the countdown.',`<select data-preference="minutesDelay" aria-label="Minutes delay">${['0','5','10','15','30','60','Manual'].map(x=>`<option ${String(state.minutesDelay??5)===x?'selected':''}>${x}</option>`).join('')}</select>`)}${settingRow('Wait for my notes','Restart the delay when I finish editing.',toggle('waitNotes','Wait for my notes',state.waitNotes!==false))}${settingRow('Quiet hours','Defer until the next active period.',toggle('respectQuiet','Respect quiet hours',state.respectQuiet!==false))}${settingRow('If I am in another meeting','Keep the recording local; defer the AI job.',toggle('deferInMeeting','Defer in another meeting',state.deferInMeeting!==false))}</div>`;case 'Skill & prompt':return `<h3>How the minutes are written</h3><div class="readiness mt">${icon('automation')}Selected profile skill: /meeting-minutes · v1.3</div><p class="prose mt">${esc(r.prompt)}</p><div class="notice mt">Uses the selected profile’s skill catalog. Personal skill folders are read only; nothing is copied into the vault.</div>${btn('Edit skill or prompt','edit-recipe:'+r.id,'edit','sm')}`;case 'Template':return `<div class="between"><h3>Output structure · Markdown / HTML</h3>${btn('Edit template','edit-recipe:'+r.id,'edit','sm')}</div><pre class="codebox mt">${esc(r.template)}</pre>`;case 'Outputs':return `<div class="panel">${settingRow('Meeting minutes','Local draft attached to this meeting.',tag('Always','green'))}${settingRow('Action items','Extract with owner, due date and transcript reference.',toggle('recipeActions','Extract action items',state.recipeActions!==false))}${settingRow('Knowledge updates','Propose changes; review every file before saving.',toggle('recipeKnowledge','Propose Knowledge updates',state.recipeKnowledge!==false))}${settingRow('Share with attendees','Prepare a draft. Sending requires recipient and body review.',toggle('recipeShare','Prepare attendee draft',state.recipeShare))}</div>`;case 'History':return `<div class="panel"><div class="list-row"><div class="grow"><h3>v3 · Current</h3><p>Today · added explicit owner and due date fields</p></div>${btn('Compare','recipe-history','code','sm')}</div><div class="list-row"><div class="grow"><h3>v2 · 13 Nov</h3><p>Added source references and reviewed Knowledge output</p></div>${btn('Restore as new version','restore-recipe-version','undo','sm')}</div></div>`;default:return `<h3>When this recipe applies</h3><div class="panel mt">${settingRow('Space','First match among your enabled recipes.',`<select data-preference="recipeSpace" aria-label="Recipe space">${['Any space',...state.spaces.map(x=>x.name)].map(x=>`<option ${state.recipeSpace===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`)}${settingRow('Subject contains','Match words from the calendar title.',`<input aria-label="Recipe subject rule" id="recipe-subject" value="${esc(state.recipeSubject||'sync, review')}" style="max-width:210px">`)}${settingRow('Meeting length','Skip very short meetings.',`<select data-preference="recipeLength" aria-label="Minimum meeting length">${['Any length','More than 5 min','More than 15 min','More than 30 min'].map(x=>`<option ${state.recipeLength===x?'selected':''}>${x}</option>`).join('')}</select>`)}</div><div class="readiness mt">${icon('check')}Matched 23 past meetings. Test the rule and output before using a new version.</div><div class="flex mt">${btn('Test on a past meeting','test-recipe:'+r.id,'play','primary')}${btn('Save rule','save-recipe-rule','check')}</div>`}}
const originalAutomations=pages.automations;
pages.automations=()=>{const a=state.automations.find(x=>x.id===state.routineSelected)||state.automations[0];return `${head('Automations','Routines with visible steps, sources, caps and run history.',btn('Templates','routine-templates','grid')+btn('New routine','new-automation','plus','primary'))}<div class="panel module-layout"><aside class="module-list"><div class="module-section">Your routines</div>${state.automations.map(x=>`<button class="module-item ${a.id===x.id?'active':''}" data-action="select-routine:${x.id}"><strong>${x.enabled?'●':'○'} ${esc(x.name)}</strong><small>${esc(x.schedule)}</small><small>${esc(x.last)}</small></button>`).join('')}</aside><section class="module-detail"><div class="module-subhead"><div><h2>${esc(a.name)}</h2><p class="small dim">${esc(a.profile)} · ${esc(a.delivery)}</p></div><div class="flex"><label class="toggle"><input type="checkbox" data-automation-toggle="${a.id}" aria-label="Enable ${esc(a.name)}" ${a.enabled?'checked':''}><span></span></label>${btn('Edit','edit-automation:'+a.id,'edit','sm')}${btn('Run now','run-automation:'+a.id,'play','primary sm')}</div></div>${!pluginEnabled('scheduler')?'<div class="notice amber mb">Scheduler is disabled. Enable the plugin to run routines. <a class="text-link" href="plugin.html?id=scheduler">Manage plugin</a></div>':''}<nav class="view-tabs">${['Routine','Run history','Outputs'].map(t=>`<button class="${(state.routineTab||'Routine')===t?'active':''}" data-action="routine-tab:${t}">${t}</button>`).join('')}</nav>${routineDetail(a)}</section></div>`};
function routineDetail(a){if(state.routineTab==='Run history')return `<div class="panel">${[a.last,'Yesterday · 07:30','Fri · 07:30'].map((d,i)=>`<div class="list-row"><span class="round-icon">${icon('check')}</span><div class="grow"><h3>${d}</h3><p>${i===1?'Skipped: computer asleep · caught up at 08:10':'Completed · 34 s · 14 sources · estimated $0.04'}</p></div>${btn('Inspect run','inspect-routine-run','eye','sm')}</div>`).join('')}</div>`;if(state.routineTab==='Outputs')return `<h3>Destination: ${esc(a.delivery)}</h3><p class="prose mt">A local result appears in Today and the run log. Mail, Teams and Telegram outputs are prepared drafts requiring review.</p><div class="info-box mt"><h3>Latest result</h3><p>Your morning brief has 5 points, 14 source references and 3 requests needing review.</p>${btn('Open result','morning-brief','arrow','primary sm')}</div>`;return `<div class="grid2"><div class="info-box"><h3>Trigger</h3><p>${esc(a.schedule)}</p><div class="setting-row" style="padding:12px 0 0"><span class="small">Also when critical item arrives</span>${toggle('routineEvent','Run on critical event',state.routineEvent)}</div></div><div class="info-box"><h3>Sleep & missed runs</h3><p>Catch up within 2 hours after wake. Otherwise skip and record why.</p></div></div><h3 class="mt mb">Steps · deterministic first, AI at the useful point</h3><div class="flow-row">${[['1','Read calendar','Graph + cached agenda','No model'],['2','Read Inbox','Selected priority lanes','No model'],['3','Read knowledge','Granted pages only','No model'],['4','Write brief','Your prompt + profile','AI'],['5','Check & save','Citations, cap, local output','No model']].map(([n,t,d,k])=>`<div class="flow-step ${k==='AI'?'ai':''}"><div class="step-type">${n} · ${k}</div><strong>${t}</strong><span>${d}</span></div>`).join('')}</div><div class="info-box mt"><h3>Prompt</h3><p>${esc(a.prompt)}</p></div><div class="panel mt">${settingRow('Per-run cap','$0.25 for a metered profile. Direct account billing remains provider-managed.',tag('At cap: stop'))}${settingRow('Outward delivery','Prepare a draft for recipient and content review.',tag('Approval required','blue'))}</div>`}

const graphNodes=Array.from({length:60},(_,i)=>({id:i,title:[...docNames,'Direct Claude Code','Capture rules','Meeting recipes','Source provenance','Review policy','Personal skills'][i]||['Architecture','Research','Meeting','Decision','Person','Topic'][i%6]+' '+(i+1),folder:['Workspace','Meetings','Learning','People'][i%4],type:['Concept','Meeting','Decision','Person'][i%4],isolated:i>55,index:i>=54&&i<=55,x:400+Math.cos(i*2.39996)*Math.sqrt(i+1)*37,y:270+Math.sin(i*2.39996)*Math.sqrt(i+1)*27}));
pages['knowledge-graph']=()=>{const selected=graphNodes.find(n=>n.id===Number(state.graphSelected||0));return `${vaultHeader(btn('Reset view','v2-reset-graph','refresh'))}<div class="panel panel-pad mb"><div class="graph-tools"><div class="search-field" style="max-width:240px">${icon('search')}<input id="v2-graph-search" aria-label="Find graph pages" placeholder="Search pages and paths…" value="${esc(state.graphQuery||'')}"></div><label>Color by <select data-preference="graphColor" aria-label="Graph color by">${['Folder','Type','Tag'].map(t=>`<option ${state.graphColor===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Local depth <select data-preference="graphDepth" aria-label="Local graph depth">${['All','1','2','3'].map(t=>`<option ${state.graphDepth===t?'selected':''}>${t}</option>`).join('')}</select></label><label><input type="checkbox" data-setting="graphHideIndex" ${state.graphHideIndex!==false?'checked':''}>Hide index pages</label><label><input type="checkbox" data-setting="graphIsolated" ${state.graphIsolated!==false?'checked':''}>Show isolated</label></div></div><div class="detail-grid"><section class="panel"><div class="v2-graph"><svg viewBox="0 0 800 540" role="img" aria-label="Interactive knowledge graph"><g id="v2-graph-drawing" transform="translate(${400-(state.graphZoom||1)*400} ${270-(state.graphZoom||1)*270}) scale(${state.graphZoom||1})">${graphNodes.filter(n=>n.id>1&&!n.isolated).map(n=>`<line x1="${n.x}" y1="${n.y}" x2="${graphNodes[Math.floor(n.id/3)].x}" y2="${graphNodes[Math.floor(n.id/3)].y}"/>`).join('')}${graphNodes.map(n=>`<g data-v2-node="${n.id}" data-graph-title="${esc(n.title.toLowerCase())}" role="button" tabindex="0" aria-label="Inspect ${esc(n.title)}" data-action="select-graph-node:${n.id}" ${((n.index&&state.graphHideIndex!==false)||(n.isolated&&state.graphIsolated===false))?'style="display:none"':''}><circle cx="${n.x}" cy="${n.y}" r="${n.id===selected.id?11:n.id<10?7:4}" fill="${['var(--accent)','var(--blue)','var(--green)','var(--amber)'][(n.id+(state.graphColor==='Type'?1:state.graphColor==='Tag'?2:0))%4]}" stroke="var(--surface)" stroke-width="2"/>${n.id<10||n.id===selected.id?`<text x="${n.x+12}" y="${n.y+4}">${esc(n.title)}</text>`:''}</g>`).join('')}</g></svg><div class="graph-controls"><button class="icon-btn" data-action="graph-zoom:-0.2" aria-label="Zoom out">−</button><button class="icon-btn" data-action="graph-zoom:0.2" aria-label="Zoom in">+</button><button class="icon-btn" data-action="v2-reset-graph" aria-label="Reset graph">${icon('refresh')}</button></div></div><div class="panel-foot"><span>60 sample nodes · 214 pages in vault</span><span>Click a node · local depth filters neighbors</span></div></section><aside class="panel panel-pad"><span class="chip">${selected.folder}</span><h2 class="mt">${esc(selected.title)}</h2><p class="prose mt">Connected context from your own Markdown links. Follow a source or ask about this page.</p><div class="compact-kpi"><div><strong>${selected.id%8+3}</strong><span>backlinks</span></div><div><strong>${selected.id%5+2}</strong><span>outgoing links</span></div></div><div class="flex wrap">${linkBtn('Open page','knowledge-pages.html?doc='+encodeURIComponent(selected.title),'file','primary sm')}${linkBtn('Ask about it','knowledge-ask.html?ask='+encodeURIComponent('Explain '+selected.title),'spark','sm')}</div><div class="line"></div><h3>Connected pages</h3>${graphNodes.filter(n=>Math.abs(n.id-selected.id)<4&&n.id!==selected.id).map(n=>`<button class="text-link" style="display:block;text-align:left;padding:7px 0;font-size:10px" data-action="select-graph-node:${n.id}">${esc(n.title)}</button>`).join('')}</aside></div>`};

pages.space=()=>{const s=state.spaces[Number(new URLSearchParams(location.search).get('space')||0)]||state.spaces[0],tab=state.spaceTab||'Overview';return `${head(esc(s.name),esc(s.desc),btn('Space settings','edit-space','settings')+btn('Ask this space','ask-space','spark','primary'))}<nav class="view-tabs">${['Overview','Meetings','Work','Inbox','Knowledge','People','Sources'].map(t=>`<button class="${tab===t?'active':''}" data-action="space-tab:${t}">${t}</button>`).join('')}</nav>${tab==='Overview'?`<div class="detail-grid"><section class="stack">${panel('Space brief',`<div class="widget-body"><div class="doc-frontmatter">type: space-index · owner: you · source: reviewed meetings<br>path: knowledge/workspace/index.md · updated today</div><article class="prose"><h2>CodeMie personal workspace</h2><p class="mt">Bring your day, meetings and knowledge together. Keep direct Claude Code useful before a platform account is connected.</p><h3>Now</h3><ul><li>Review the CodeMie visual direction and richer Today widgets.</li><li>Validate the host contract for unchanged Echo plugins.</li><li>Keep native capture and Graph permissions explicit.</li></ul></article></div>`,btn('Edit in Knowledge','space-edit-brief','edit','ghost sm'),'book')}${panel('Open risks & decisions',`<div class="decision-row"><span class="decision-icon">${icon('shield')}</span><div class="grow"><h3>Echo runtime license and host parity</h3><p>Reuse requires an explicit licensing approach and cross-host conformance checks.</p><a class="source" href="plugin-studio.html">Plugin investigation</a></div></div><div class="decision-row"><span class="decision-icon">${icon('book')}</span><div class="grow"><h3>Vault write policy</h3><p>Reviewed diffs by default. Confirm the read-only option and selected profile grants.</p><a class="source" href="knowledge-setup.html">Access settings</a></div></div>`,'','inbox')}</section><aside class="stack">${panel('Connected context',`<div class="widget-body"><div class="metric-row"><span>Meetings</span><b>6</b></div><div class="metric-row"><span>Knowledge pages</span><b>24</b></div><div class="metric-row"><span>People</span><b>4</b></div><div class="metric-row"><span>AI profile</span><b>Direct Claude Code</b></div><div class="metric-row"><span>Minutes recipe</span><b>Design review</b></div><div class="flex wrap mt">${btn('Membership rules','space-membership','filter','sm')}${btn('Manage sources','space-sources','link','sm')}</div></div>`,'','link')}${panel('People',`<a class="list-row" href="people.html"><span class="avatar">AM</span><div class="grow"><h3>Alex Morgan</h3><p>3 meetings · product design</p></div></a><a class="list-row" href="people.html"><span class="avatar blue">JT</span><div class="grow"><h3>Jamie Taylor</h3><p>4 meetings · engineering</p></div></a>`,'','users')}</aside></div>`:tab==='Meetings'?`<div class="panel">${meetingNames.map((n,i)=>`<a class="list-row" href="meeting.html?meeting=${i}">${icon('video')}<div class="grow"><h3>${n}</h3><p>Source-linked minutes, actions and decisions</p></div>${icon('chevron')}</a>`).join('')}</div>`:tab==='Work'?`<div class="panel"><div class="panel-head"><h2>Personal commitments</h2>${tag('From meeting sources')}</div>${[['Send Jamie the prototype review','You · today · design review 18:24'],['Review capture controls','Alex · today · Teams 09:12'],['Complete host service inventory','Jamie · tomorrow · meeting 24:16']].map(([n,d])=>`<div class="list-row">${icon('check')}<div class="grow"><h3>${n}</h3><p>${d}</p></div>${btn('Review source','go:meeting','file','sm')}</div>`).join('')}</div>`:tab==='Inbox'?`<div class="panel">${mailItems.slice(0,3).map(m=>`<a class="list-row" href="inbox.html"><span class="avatar">${m.initials}</span><div class="grow"><h3>${m.subject}</h3><p>${m.from} · ${m.time}</p></div>${icon('chevron')}</a>`).join('')}</div>`:tab==='Knowledge'?`<div class="panel">${docNames.map(t=>`<a class="list-row" href="knowledge-pages.html?doc=${encodeURIComponent(t)}">${icon('file')}<span class="grow">${t}</span>${icon('chevron')}</a>`).join('')}</div>`:tab==='People'?`<div class="grid2">${samplePeople.map(([i,n,r],idx)=>`<button class="panel panel-pad flex" data-action="person:${idx}"><span class="avatar">${i}</span><div><h3>${n}</h3><p class="small">${r}</p></div></button>`).join('')}</div>`:`<div class="panel">${settingRow('Knowledge','~/AI/personal-knowledge/knowledge/workspace',linkBtn('Vault access','knowledge-setup.html','folder','sm'))}${settingRow('Teams channel','Workspace redesign · selected conversations only',linkBtn('Connection','settings-connections.html','teams','sm'))}${settingRow('GitHub repositories','workspace/connect · workspace/notes',btn('Configure plugin','github-repos','github','sm'))}${settingRow('Membership','Subject and source rules decide which items belong.',btn('Edit membership','space-membership','filter','sm'))}</div>`}<div class="prototype-disclaimer">A space organizes context. It does not grant a plugin access or share your files.</div>`};
